Animated Circular Progress Bar is a component that displays a circular gauge with a percentage value.

Official component guide: https://axuj.github.io/magicui-solid/docs/components/animated-circular-progress-bar/. Component source: https://raw.githubusercontent.com/axuj/magicui-solid/3100c2f704620f96dc431dd86f86bbbf9bb05965/src/registry/magicui/animated-circular-progress-bar.tsx.

Source-pinned component props:
```ts
interface AnimatedCircularProgressBarProps {
  max?: number
  min?: number
  value: number
  gaugePrimaryColor: string
  gaugeSecondaryColor: string
  class?: string
}
```

Original documented Solid example:
```tsx
import { createSignal, onCleanup, onMount } from "solid-js";

import { AnimatedCircularProgressBar } from "@/registry/magicui/animated-circular-progress-bar";

function waitForPaint() {
  return new Promise<void>(resolve =>
    requestAnimationFrame(() => requestAnimationFrame(() => resolve())),
  )
}

const bump = (prev: number) => (prev === 100 ? 0 : prev + 10)

export function AnimatedCircularProgressBarDemo() {
  const [value, setValue] = createSignal(0)

  onMount(() => {
    const ac = new AbortController()

    waitForPaint().then(() => {
      if (ac.signal.aborted)
        return
      setValue(bump)
      const timer = setInterval(setValue, 2000, bump)
      ac.signal.addEventListener('abort', () => clearInterval(timer))
    })

    onCleanup(() => ac.abort())
  })

  return (
    <AnimatedCircularProgressBar
      value={value()}
      gaugePrimaryColor="rgb(79 70 229)"
      gaugeSecondaryColor="rgba(0, 0, 0, 0.1)"
    />
  )
}
```

